  render: () => {
    const root = document.createElement('div');
    root.style.cssText = 'background: var(--sp-bg); ' + 'height: 100vh; max-width: 400px; padding: 20px; display: flex; flex-direction: column; gap: 12px;' + ' font-family: ui-sans-serif, system-ui, -apple-system, sans-serif; color: var(--sp-text);';
    const heading = document.createElement('div');
    heading.style.cssText = 'font-size: 12px; color: var(--sp-muted); flex-shrink: 0;';
    heading.textContent = 'Fixed-height container (100vh). Expand all groups — the catalog body should scroll. ' + 'Planned rounds are dimmed.';
    root.appendChild(heading);
    const store = new ProfileStore(makeBaseConfig({
      initialProfile: VALID_PROFILE
    }));
    const panel = buildRoundCatalog({
      onSearchChange: q => {
        store.setCatalogSearch(q);
        panel.update(store.getState());
      },
      onGroupByChange: mode => {
        store.setCatalogGroupBy(mode);
        panel.update(store.getState());
      }
    });

    // Panel fills remaining space in the flex column
    panel.element.style.flex = '1';
    panel.element.style.minHeight = '0';
    root.appendChild(panel.element);
    panel.update(store.getState());
    return root;
  }
